/* prog25_balanced_multitype.c
 *
 * Reimplementation of the original binary's behaviour:
 *   - If no argument is supplied, prints "BALANCED".
 *   - Otherwise checks whether the argument contains a balanced sequence of
 *     parentheses '()', brackets '[]' and braces '{}'.
 *   - Prints "BALANCED" or "UNBALANCED" accordingly.
 *
 * The program ignores any characters other than the six bracket symbols.
 */

#include <stdio.h>
#include <string.h>
#include <stdlib.h>

int main(int argc, char *argv[])
{
    /* No user supplied string -> BALANCED (matches the original binary). */
    if (argc < 2) {
        puts("BALANCED");
        return 0;
    }

    const char *s = argv[1];
    size_t len = strlen(s);

    /* Simple stack implemented with a dynamic array. */
    char *stack = malloc(len + 1);   /* at most one push per character */
    if (!stack) {
        perror("malloc");
        return 1;
    }
    size_t sp = 0;   /* stack pointer */

    int balanced = 1;   /* assume balanced until a mismatch is found */

    for (size_t i = 0; i < len && balanced; ++i) {
        char c = s[i];
        switch (c) {
            case '(':
            case '[':
            case '{':
                stack[sp++] = c;          /* push opening bracket */
                break;

            case ')':
                if (sp == 0 || stack[sp - 1] != '(') {
                    balanced = 0;
                } else {
                    --sp;                 /* pop matching '(' */
                }
                break;

            case ']':
                if (sp == 0 || stack[sp - 1] != '[') {
                    balanced = 0;
                } else {
                    --sp;                 /* pop matching '[' */
                }
                break;

            case '}':
                if (sp == 0 || stack[sp - 1] != '{') {
                    balanced = 0;
                } else {
                    --sp;                 /* pop matching '{' */
                }
                break;

            default:
                /* All other characters are ignored. */
                break;
        }
    }

    /* If there are leftover opening brackets, the string is unbalanced. */
    if (sp != 0) balanced = 0;

    puts(balanced ? "BALANCED" : "UNBALANCED");

    free(stack);
    return 0;
}
